<?php /** Reportes con exportación a CSV desde el navegador. */
$ado = array_filter($solicitudes, fn($s) => $s['estado'] === 'aprobada'); $disp = array_filter($mascotas, fn($m) => $m['estado'] === 'disponible'); ?>
<div class="d-flex justify-content-between align-items-start gap-3 flex-wrap mb-4"><div><h1 class="h2 mb-1">Reportes y estadísticas</h1><p class="text-secondary mb-0">Indicadores principales de la plataforma</p></div></div>
<div class="row g-3 mb-4"><?php foreach ([[count($ado),'Adopciones realizadas'],[count(array_filter($solicitudes, fn($s) => $s['estado'] === 'pendiente')),'Solicitudes pendientes'],[count($disp),'Mascotas disponibles'],[count(array_filter($solicitudes, fn($s) => $s['estado'] === 'rechazada')),'Solicitudes rechazadas']] as [$n,$l]): ?>
  <div class="col-6 col-lg-3"><div class="card border-0 shadow-sm rounded-4 p-3"><div class="display-6 fw-bold mb-1"><?= $n ?></div><div class="small fw-bold text-secondary"><?= $l ?></div></div></div><?php endforeach; ?></div>
<div class="card border-0 shadow-sm rounded-4 p-4 mb-3"><div class="d-flex justify-content-between align-items-center mb-3"><div class="small text-uppercase fw-bold text-secondary mb-0">Adopciones realizadas</div><button class="btn btn-sm btn-outline-dark" data-csv="#t-ado" data-file="adopciones_adoptme.csv"><i class="bi bi-download me-1"></i>Exportar CSV</button></div>
  <div class="table-responsive"><table class="table table-hover mb-0" id="t-ado"><thead><tr><th>Mascota</th><th>Adoptante</th><th>Fecha</th></tr></thead><tbody>
  <?php foreach ($ado as $s): $p = Mascota::buscar($s['mascota_id']); ?><tr><td><?= e($p['nombre']) ?></td><td><?= e($s['solicitante']) ?></td><td><?= e($s['fecha']) ?></td></tr><?php endforeach; ?></tbody></table></div></div>
<div class="card border-0 shadow-sm rounded-4 p-4"><div class="d-flex justify-content-between align-items-center mb-3"><div class="small text-uppercase fw-bold text-secondary mb-0">Mascotas disponibles</div><button class="btn btn-sm btn-outline-dark" data-csv="#t-dis" data-file="mascotas_disponibles_adoptme.csv"><i class="bi bi-download me-1"></i>Exportar CSV</button></div>
  <div class="table-responsive"><table class="table table-hover mb-0" id="t-dis"><thead><tr><th>Nombre</th><th>Especie</th><th>Raza</th></tr></thead><tbody>
  <?php foreach ($disp as $m): ?><tr><td><?= e($m['nombre']) ?></td><td><?= e($m['especie']) ?></td><td><?= e($m['raza']) ?></td></tr><?php endforeach; ?></tbody></table></div></div>
